#!/usr/bin/env bash
#
# Generates src/gen/emoji_list.c: the emoji the keyboard offers (ui/keyboard.c), those with a
# Noto image (package noto-emoji), in Unicode's order, by category as on Android,
# without the components (skin tones, hair) that have no image. Each is UTF-8 as
# typed (with U+FE0F where it is fully qualified); labels compose them.
#
# Run in `nix develop` (jq), after Buildroot downloaded noto-emoji:
#   external/package/phone-ui/gen-emoji.sh
#

set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
version="$(sed -n 's/^NOTO_EMOJI_VERSION = //p' "$here/../noto-emoji/noto-emoji.mk")"
archive="$here/../../../dl/noto-emoji/emoji-datasource-google-$version.tgz"
out="$here/src/gen/emoji_list.c"

# The order of the keyboard's tabs (ui/keyboard.c, KB_EMOJI_TABS)
cats='["Smileys & Emotion","People & Body","Animals & Nature","Food & Drink",
       "Activities","Travel & Places","Objects","Symbols","Flags"]'

tar -xzOf "$archive" package/emoji.json | jq -r --argjson cats "$cats" '
	[.[] | select(.has_img_google and (.category as $c | $cats | index($c)))] as $all
	| ($cats | map(. as $c | [$all[] | select(.category == $c)] | sort_by(.sort_order))) as $by
	| "/* Generated by gen-emoji.sh from emoji-datasource-google '"$version"' (emoji.json), do not edit */",
	  "",
	  "/* The keyboard'"'"'s emoji, by category (emoji_category_end), in Unicode'"'"'s order */",
	  "const char *const emoji_list[] = {",
	  ($by | to_entries[] | "\t/* \($cats[.key]) */",
	    (.value[] | "\t\"" + (.unified | split("-") | map("0x" + . | ltrimstr("0x") | explode | . as $h
	      | reduce .[] as $d (0; . * 16 + (if $d >= 65 then $d - 55 else $d - 48 end))) | implode) + "\",")),
	  "};",
	  "",
	  "/* Where each category ends in emoji_list */",
	  "const unsigned emoji_category_end[] = {",
	  ([foreach $by[] as $c (0; . + ($c | length))] | map("\t\(.),") | .[]),
	  "};"
' > "$out"
echo "$out: $(grep -c '^	"' "$out") emoji"
